<?php
require_once __DIR__.'/../../config/config.php';$user=require_roles(['ADMIN','HR']);$pdo=db();$q=$pdo->prepare('SELECT r.*,e.employee_number,e.first_name,e.last_name,u.username requester FROM profile_change_requests r JOIN employees e ON e.id=r.employee_id JOIN users u ON u.id=r.requester_user_id WHERE r.id=?');$q->execute([(int)($_GET['id']??0)]);$request=$q->fetch();if(!$request){http_response_code(404);exit('Request not found.');}$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$decision=$_POST['decision']??'';try{review_change_request($pdo,(int)$request['id'],(int)$user['id'],$decision,trim((string)$_POST['review_reason']));flash('success','Request reviewed successfully.');redirect('admin/change-requests/view.php?id='.$request['id']);}catch(Throwable $exception){$error=$exception->getMessage();}}$pageTitle='Review change request';require __DIR__.'/../../includes/header.php';?><div class="mb-7"><a href="index.php" class="text-sm font-bold text-teal-700">← Change requests</a><h1 class="font-display text-3xl font-bold mt-2">Review request #<?=e($request['id'])?></h1><p class="text-sm text-slate-500"><?=e($request['first_name'].' '.$request['last_name'].' · '.$request['employee_number'])?></p></div><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 p-3 text-sm text-red-700"><?=e($error)?></div><?php endif;?><section class="bg-white border rounded-xl p-6 max-w-3xl"><div class="grid md:grid-cols-2 gap-5 text-sm mb-7"><?php foreach(['Request type'=>'request_type','Field'=>'requested_field','Current value'=>'old_value','Requested value'=>'requested_value','Reason'=>'reason','Submitted'=>'created_at','Status'=>'status','Requester'=>'requester'] as $label=>$field):?><div><p class="text-xs text-slate-400"><?=e($label)?></p><p class="font-semibold mt-1 whitespace-pre-wrap"><?=e($request[$field]??'—')?></p></div><?php endforeach;?></div><?php if($request['status']==='PENDING'):?><form method="post" class="border-t pt-6"><?= csrf_field() ?><label class="block text-sm font-semibold">HR remarks / rejection reason<textarea name="review_reason" rows="4" class="field"></textarea></label><div class="flex gap-3 mt-5"><button name="decision" value="APPROVED" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">Approve request</button><button name="decision" value="REJECTED" class="rounded-lg bg-red-700 px-5 py-3 text-sm font-bold text-white">Reject request</button></div></form><?php else:?><p class="border-t pt-5 text-sm text-slate-500">This request has already been <?=e(strtolower($request['status']))?>.</p><?php endif;?></section><?php require __DIR__.'/../../includes/footer.php';